function toBrazilDate(date) {
  const d = new Date(date);
  d.setHours(d.getHours() - 3);
  return d.toISOString().slice(0, 10);
}

const todayBR = toBrazilDate(new Date());

for (const item of $input.all()) {
  const createdAt = item.json.created_at;
  item.json.isCreatedToday = createdAt
    ? toBrazilDate(createdAt) === todayBR
    : false;
}

return $input.all();

return $input.all().map(item => {
  const partes = item.json.cnpj_cliente.split('-');

  return {
    json: {
      ...item.json,
      cnpj: partes[0],
      nome_empresa: partes.slice(1).join(' ')
    }
  };
});

